rule "parse_ssh_messages"
when
    has_field("message")
then
    let msg_str = to_string($message.message);

    // --- SSH login success (password or publickey) ---
    set_field("ssh_login_username",
        regex(pattern: "Accepted (?:password|publickey) for (\\S+) from ([0-9]{1,3}(?:\\.[0-9]{1,3}){3})", value: msg_str)["0"]
    );
    set_field("ssh_login_source",
        regex(pattern: "Accepted (?:password|publickey) for (\\S+) from ([0-9]{1,3}(?:\\.[0-9]{1,3}){3})", value: msg_str)["1"]
    );

    // --- SSH failed login (normal failed password) ---
    set_field("ssh_fail_username",
        regex(pattern: "Failed password for (?:invalid user )?(\\S+) from ([0-9]{1,3}(?:\\.[0-9]{1,3}){3})", value: msg_str)["0"]
    );
    set_field("ssh_fail_source",
        regex(pattern: "Failed password for (?:invalid user )?(\\S+) from ([0-9]{1,3}(?:\\.[0-9]{1,3}){3})", value: msg_str)["1"]
    );

    // --- Invalid user only ---
    set_field("ssh_fail_invalid_username",
        regex(pattern: "Failed password for invalid user (\\S+) from", value: msg_str)["0"]
    );

    // --- PAM authentication failures ---
    set_field("ssh_pam_fail_username",
        regex(pattern: "pam_unix\\(sshd:auth\\): authentication failure; .* user=(\\S+)", value: msg_str)["0"]
    );
    set_field("ssh_pam_fail_source",
        regex(pattern: "pam_unix\\(sshd:auth\\): authentication failure; .* rhost=([0-9]{1,3}(?:\\.[0-9]{1,3}){3})", value: msg_str)["0"]
    );

end
